def main():
    rows=[]
    intro = '''# Приложение А Матрица соответствия требованиям договора

Матрица сопоставляет каждый переданный пункт задания с содержанием отчёта, доступными результатами и границами подтверждения. Текст требований воспроизведён отдельно от пояснений автора. Номера А01–А19, К01–К07, Р01–Р10 и С01–С05 введены для навигации; они не являются нумерацией исходного договора.

Основная цель отчёта — разработка методики определения УО. ФВ сохранена как дополнительное исследовательское направление. Её результаты не используются для повышения статуса проверки УО и не подменяют обязательный результат.

«Представлено» означает наличие описания и названного материала. «Частично подтверждено» указывает на ограниченную проверку; «не подтверждено» — на отсутствие доказательства конкретного положительного требования в имеющемся корпусе. «Отдельная поставка» отделяет научное описание от фактического наличия файлов в текущем редакционном комплекте. Отрицательный результат подтверждает выполнение соответствующего исследовательского опыта, но не превращается в положительную характеристику методики.
'''
    parts=[intro]
    for prefix,title,items in GROUPS:
        parts.extend([f'\n## {title}\n', '<details>',f'<summary>Таблица А.{len(parts)//100 + list(g[0] for g in GROUPS).index(prefix)+1} — {title}</summary>\n', '| Код | Требование договора | Раздел и доказательный материал | Статус и ограничение |','|---|---|---|---|'])
        for i,(quote,evidence,status) in enumerate(items,1):
            code=f'{prefix}{i:02d}'
            rows.append(dict(id=code,group=title,requirement=quote,evidence=evidence,status=status))
            parts.append(f'| {code} | {quote} | {evidence} | {status} |')
        parts.append('\n</details>\n')
    matrix='\n'.join(parts)+'\n'
    (ROOT/'contract_matrix.md').write_text(matrix,encoding='utf-8')
    (ROOT/'contract_requirements.json').write_text(json.dumps({'source':'Фрагмент договора, предоставленный автором в чате; пояснения в скобках не включены в требования','decision_date':'2026-10-29','primary_endpoint':'УО','additional_direction':'ФВ','requirements':rows},ensure_ascii=False,indent=2),encoding='utf-8')
    appendix=(OLD/'appendices.md').read_text(encoding='utf-8')
    tail=appendix[appendix.index('# Приложение Б'):]
    (ROOT/'appendices.md').write_text(matrix+'\n'+tail,encoding='utf-8')
    sources=[]
    for p in sorted(OLD.glob('chapters/*.md'))+[OLD/n for n in ['front_matter.md','conclusion.md','appendices.md','build_manifest.json']]:
        sources.append({'source_id':p.name,'file':p.relative_to(ROOT.parent).as_posix(),'sha256':hashlib.sha256(p.read_bytes()).hexdigest()})
    doc=OLD/'deliverables/Отчёт_ГПХ_РНЦХ_20261028_для_рецензирования.docx'
    sources.append({'source_id':'prior_review_docx','file':doc.relative_to(ROOT.parent).as_posix(),'sha256':hashlib.sha256(doc.read_bytes()).hexdigest()})
    (ROOT/'reviews/input_snapshot.json').write_text(json.dumps({'date':'2026-10-29','mode':'manuscript_revision','figure_mode':'with_figures','formatting_mode':'section_only','formatting_basis':'Сохранено оформление существующего научного отчёта Word','sources':sources},ensure_ascii=False,indent=2),encoding='utf-8')
    print(json.dumps({'requirements':len(rows),'groups':{p:len(items) for p,_,items in GROUPS}},ensure_ascii=False))

if __name__=='__main__': main()
